INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am3_l32_gp6','am3_l32','词汇辨析(salvage/scour/bullion)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l32','harbor','harbour','港口;拼写差异,美语无 u') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l32','gray','grey','灰色;拼写差异,美语 gray') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l32','mail','post','邮件;美语 mail,英式 post') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l32','flashlight','torch','手电筒;美语 flashlight,英式 torch') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l32','piece together','',NULL,'/piːs təˈɡeðər/','The captain pieced together the whole story.','船长把整个故事拼凑了出来。','Detectives pieced together the clues.','侦探们把线索拼凑起来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l32','come to light','',NULL,'/kʌm tə laɪt/','New information came to light.','新的信息浮出水面。','The truth finally came to light.','真相终于大白。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l32','under the impression','',NULL,'/ˈʌndər ði ɪmˈpreʃən/','The crew were under the impression that the lost ship had been found.','船员们以为找到了那艘失踪的船。','I was under the impression that you had left.','我还以为你已经走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l32','give up','',NULL,'/ɡɪv ʌp/','He was told to give up the search.','有人叫他放弃搜寻。','Never give up your dreams.','永远别放弃你的梦想。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp1','choice','{"stem":"\"The Elkor had been ___ the Barents Sea for weeks.\"(过去完成进行时 had been + -ing)","options":["searched","searching","search","to search"],"answer_index":1,"stem_cn":"埃尔科号已在巴伦支海搜寻了数周。","explanation_cn":"过去完成进行时 had been + 动词-ing,表到过去某刻“一直在做”。✓ had been searching for weeks. ✗ searched / search / to search:had been 后接 -ing。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp1','choice','{"stem":"\"By noon the crew ___ working for six hours.\"(表\"到过去某刻一直在做\",填助动词部分)","options":["had been","were","have been","has been"],"answer_index":0,"stem_cn":"到中午时,船员们已连续工作了六小时。","explanation_cn":"到过去某一刻“一直在做”,助动词部分用 had been(后接 -ing)。✓ the crew had been working for six hours. ✗ have been / has been(现在)/ were:过去完成进行用 had been。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp1','choice','{"stem":"\"The ship ___ carrying gold when it sank.\"(表\"沉没前一直载着\",填助动词部分)","options":["was been","has been","had been","had"],"answer_index":2,"stem_cn":"那船沉没时一直载着黄金。","explanation_cn":"“沉没前一直载着”,到过去某刻的持续,用 had been + -ing。✓ The ship had been carrying gold. ✗ has been(现在)/ was been(错)/ had(缺 been):用 had been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp2','choice','{"stem":"\"A radio message had been ___ by the captain.\"(过去完成被动 had been + 过去分词)","options":["received","receiving","receives","receive"],"answer_index":0,"stem_cn":"船长收到了一条无线电讯息。","explanation_cn":"过去完成时的被动 had been + 过去分词。✓ A message had been received. ✗ receiving / receive / receives:被动用过去分词 received。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp2','choice','{"stem":"\"The ship had been ___ many years before they found it.\"(过去完成被动 had been + 过去分词)","options":["sank","sunk","sink","sinking"],"answer_index":1,"stem_cn":"他们找到时,那船已沉没多年。","explanation_cn":"过去完成时的被动 had been + 过去分词;sink 的过去分词是 sunk。✓ had been sunk many years before. ✗ sank(过去式)/ sinking / sink:被动用 sunk。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp2','choice','{"stem":"\"From the heavy bell, the captain realized the ship ___ an old liner.\"(对过去的推测\"一定曾是\")","options":["must have been","must have","must be","can be"],"answer_index":0,"stem_cn":"从那口大钟看,船长断定它一定曾是艘旧客轮。","explanation_cn":"对过去的推测“一定曾是”,用 must have been + 名词。✓ the ship must have been an old liner. ✗ must be(推测现在)/ must have(缺 been)/ can be:推测过去用 must have been。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp3','choice','{"stem":"\"The sailor had ___ many letters from his wife.\"(\"收到\"别人寄来的东西用哪个动词)","options":["fetched","received","brought","taken"],"answer_index":1,"stem_cn":"那水手收到过妻子许多来信。","explanation_cn":"“收到(别人寄/给的东西)”用 receive。✓ had received many letters from his wife. ✗ taken / brought / fetched:收到用 receive。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp3','choice','{"stem":"\"Please ___ this box to the captain''s cabin.\"(\"把…拿去\"用哪个动词)","options":["receive","accept","get received","take"],"answer_index":3,"stem_cn":"请把这箱子拿到船长舱去。","explanation_cn":"“把某物拿去(别处)”用 take。✓ take this box to the cabin. ✗ receive(收到)/ accept / get received:拿去用 take。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp3','choice','{"stem":"\"She was glad to ___ a gift on her birthday.\"(\"得到、收到\"礼物用哪个动词)","options":["take","receive","fetch","bring"],"answer_index":1,"stem_cn":"她很高兴在生日收到礼物。","explanation_cn":"“得到、收到”礼物用 receive。✓ receive a gift on her birthday. ✗ take / bring / fetch:收到用 receive。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp4','choice','{"stem":"\"The table was covered with a clean white ___.\"(\"一块布料\"用哪个词)","options":["cloths only","clothes","clothing","cloth"],"answer_index":3,"stem_cn":"桌上铺着一块干净的白布。","explanation_cn":"“布料、一块布”用 cloth(可数,a cloth)。✓ a clean white cloth. ✗ clothes(衣服)/ clothing(衣物总称)/ cloths only:一块布用 cloth。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp4','choice','{"stem":"\"He put on warm ___ before going out.\"(\"衣服(复数)\"日常用哪个词)","options":["a clothes","clothes","cloth","clothing"],"answer_index":1,"stem_cn":"出门前他穿上暖和的衣服。","explanation_cn":"“衣服”日常用 clothes(永远复数)。✓ put on warm clothes. ✗ cloth(布)/ clothing(总称)/ a clothes(无此说法):衣服用 clothes。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp4','choice','{"stem":"\"The store sells food, shoes, and ___.\"(\"衣物\"的不可数总称用哪个词)","options":["a clothes","clothe","clothing","cloth"],"answer_index":2,"stem_cn":"那家店卖食品、鞋子和衣物。","explanation_cn":"“衣物”的不可数总称用 clothing(前不加 a、不加 s)。✓ food, shoes, and clothing. ✗ cloth(布)/ clothe(动词)/ a clothes:总称用 clothing。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp5','choice','{"stem":"\"The items were ___ to the surface for everyone to see.\"(\"拿到(朝说话人这边)\"用哪个)","options":["brought","taken","sent away","fetched back"],"answer_index":0,"stem_cn":"那些物件被拿到水面上给大家看。","explanation_cn":"“拿到(朝说话人)这边”用 bring,过去分词 brought。✓ items were brought to the surface. ✗ taken(拿走)/ sent away / fetched back:拿到这边用 bring。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp5','choice','{"stem":"\"Please ___ these boxes away from here.\"(\"(从这里)拿走\"用哪个)","options":["fetch","receive","bring","take"],"answer_index":3,"stem_cn":"请把这些箱子从这儿拿走。","explanation_cn":"“(从这里)拿走”用 take。✓ take these boxes away. ✗ bring(拿来)/ fetch(取来)/ receive:拿走用 take。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp5','choice','{"stem":"\"Could you ___ me a glass of water?\"(\"去把…取来(再回来)\"用哪个)","options":["send","fetch","take","receive"],"answer_index":1,"stem_cn":"你能去给我取杯水来吗?","explanation_cn":"“去把某物取来再回来”用 fetch。✓ fetch me a glass of water. ✗ take(拿走)/ receive(收到)/ send:去取来用 fetch。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp6','choice','{"stem":"\"To bring a sunken ship or its goods up from the sea is to ___.\"(\"打捞\"用哪个词)","options":["sink","sail","float","salvage"],"answer_index":3,"stem_cn":"把沉船或其货物捞起。","explanation_cn":"把沉船或其货物从海里捞起是 salvage(打捞)。✓ salvage from the wreck. ✗ sink 使下沉;✗ sail 航行;✗ float 漂浮——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp6','choice','{"stem":"\"To search a place thoroughly is to ___ it.\"(\"彻底搜索\"用哪个词)","options":["close","ignore","scour","decorate"],"answer_index":2,"stem_cn":"彻底搜遍某处。","explanation_cn":"把某处彻底搜遍是 scour。✓ the sea bed was scoured. ✗ ignore 忽视;✗ decorate 装饰;✗ close 关闭——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',5,'am3_l32_gp6','choice','{"stem":"\"Bars of gold or silver are called ___.\"(\"金条、金银块\"用哪个词)","options":["cloth","bullion","chest","cargo"],"answer_index":1,"stem_cn":"成条的金银。","explanation_cn":"成条的金或银叫 bullion(金条、金银块)。✓ gold bullion. ✗ cargo 货物;✗ cloth 布;✗ chest 箱子——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"salvage 的意思是:","options":["打捞,营救","出售","驾驶","建造"],"answer_index":0,"explanation_cn":"salvage = 打捞、营救。✓ salvage as much as possible 尽量打捞。\n顺带记:建造 = build;驾驶 = steer;出售 = sell."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"sunken 的意思是:","options":["巨大的","崭新的","漂浮的","沉没的"],"answer_index":3,"explanation_cn":"sunken = 沉没的。✓ the sunken ship 那艘沉船。\n顺带记:漂浮的 = floating;崭新的 = brand-new;巨大的 = huge."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"cargo 的意思是:","options":["货物","风暴","港口","船员"],"answer_index":0,"explanation_cn":"cargo = 货物。✓ a cargo of gold bullion 一批黄金货物。\n顺带记:船员 = crew;港口 = harbor;风暴 = storm."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"belongings 的意思是:","options":["债务","传言","命令","所有物,财物"],"answer_index":3,"explanation_cn":"belongings = 所有物、财物。✓ personal belongings 私人物品。\n顺带记:债务 = debt;命令 = order;传言 = rumor."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"wreck 的意思是:","options":["沉船残骸","码头","灯塔","救生艇"],"answer_index":0,"explanation_cn":"wreck = 沉船残骸。✓ salvage from the wreck 从残骸中打捞。\n顺带记:灯塔 = lighthouse;码头 = dock;救生艇 = lifeboat."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',6,NULL,'choice','{"stem":"piece(v.) 的意思是:","options":["丢弃","拼合,拼凑","隐藏","撕碎"],"answer_index":1,"explanation_cn":"piece(v.) = 拼合、拼凑;piece together。✓ piece together the information 把线索拼凑起来。\n顺带记:撕碎 = tear up;丢弃 = discard;隐藏 = hide."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',7,NULL,'cloze','{"stem":"第 1 空","context":"The Elkor had been ___1___ the Barents Sea for weeks. A message had been ___2___ telling the captain to stop, but he tried once more. A chest was raised, yet the crew were wrong to think the lost ship ___3___ been found. From an old bell, the captain realized the wreck ___4___ have been an ocean liner.","blank_no":1,"options":["searching","searched","search","searches"],"answer_index":0,"explanation_cn":"过去完成进行时 had been + -ing。✓ The Elkor had been searching the Barents Sea for weeks."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',7,NULL,'cloze','{"stem":"第 2 空","context":"The Elkor had been ___1___ the Barents Sea for weeks. A message had been ___2___ telling the captain to stop, but he tried once more. A chest was raised, yet the crew were wrong to think the lost ship ___3___ been found. From an old bell, the captain realized the wreck ___4___ have been an ocean liner.","blank_no":2,"options":["received","receiving","receive","receives"],"answer_index":0,"explanation_cn":"过去完成被动 had been + 过去分词。✓ A message had been received telling the captain to stop."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',7,NULL,'cloze','{"stem":"第 3 空","context":"The Elkor had been ___1___ the Barents Sea for weeks. A message had been ___2___ telling the captain to stop, but he tried once more. A chest was raised, yet the crew were wrong to think the lost ship ___3___ been found. From an old bell, the captain realized the wreck ___4___ have been an ocean liner.","blank_no":3,"options":["had","has","was","have"],"answer_index":0,"explanation_cn":"过去完成时 had + 过去分词(had been found)。✓ the crew were wrong to think the lost ship had been found."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',7,NULL,'cloze','{"stem":"第 4 空","context":"The Elkor had been ___1___ the Barents Sea for weeks. A message had been ___2___ telling the captain to stop, but he tried once more. A chest was raised, yet the crew were wrong to think the lost ship ___3___ been found. From an old bell, the captain realized the wreck ___4___ have been an ocean liner.","blank_no":4,"options":["must","can","need","dare"],"answer_index":0,"explanation_cn":"对过去的推测“一定曾是”用 must have been。✓ the wreck must have been an ocean liner."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',8,NULL,'choice','{"stem":"What was the Elkor searching for?","options":["A sunken ship carrying gold bullion","A living whale","A lost island","A hidden harbor"],"answer_index":0,"explanation_cn":"课文说 the sunken ship he was trying to find had been carrying a precious cargo of gold bullion——他们在找一艘载着黄金的沉船。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',8,NULL,'choice','{"stem":"What did the crew actually find?","options":["A brand-new boat","An empty stretch of sea","The gold they wanted","A different ship that had sunk years before"],"answer_index":3,"explanation_cn":"课文说 What they had in fact found was a ship that had been sunk many years before——他们找到的其实是另一艘早年沉没的船。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',8,NULL,'choice','{"stem":"How did the Karen sink?","options":["It ran out of fuel","It hit an iceberg","It was caught in a violent storm","It was never explained"],"answer_index":2,"explanation_cn":"课文说 the Karen…was caught in a violent storm and went down——卡伦号遭遇猛烈风暴而沉没。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',9,NULL,'choice','{"stem":"你想说\"埃尔科号已经搜寻了数周\"(过去完成进行时):","options":["The Elkor had been searching for weeks.","The Elkor had been search for weeks.","The Elkor was been searching for weeks.","The Elkor has been searching for weeks."],"answer_index":0,"explanation_cn":"过去完成进行时 had been + -ing,表到过去某刻一直在做。✓ The Elkor had been searching for weeks. 场合:说某事到过去某刻已持续做了一段时间。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',9,NULL,'choice','{"stem":"你想说\"那船一定曾是艘旧客轮\"(对过去的推测):","options":["The ship must have be an old liner.","The ship must have been an old liner.","The ship must be an old liner.","The ship must had been an old liner."],"answer_index":1,"explanation_cn":"对过去的推测“一定曾是”用 must have been(不是 must be、也不是 must had been)。✓ The ship must have been an old liner. 场合:根据线索推断过去的情况。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',9,NULL,'choice','{"stem":"你想说\"你能去给我取杯水来吗\"(fetch):","options":["Could you bring away me a glass of water?","Could you receive me a glass of water?","Could you fetch me a glass of water?","Could you take me a glass of water?"],"answer_index":2,"explanation_cn":"“去把某物取来再回来”用 fetch。✓ Could you fetch me a glass of water? 场合:请人去取东西再拿回来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"salvage 的意思是:","options":["出售","驾驶","建造","打捞,营救"],"answer_index":3,"explanation_cn":"salvage = 打捞、营救。✓ salvage as much as possible."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"wreck 的意思是:","options":["码头","沉船残骸","灯塔","救生艇"],"answer_index":1,"explanation_cn":"wreck = 沉船残骸。✓ salvage from the wreck."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"\"The Elkor had been ___ the sea for weeks.\"(过去完成进行时 had been + -ing)","options":["searching","to search","search","searched"],"answer_index":0,"stem_cn":"埃尔科号已在海上搜寻了数周。","explanation_cn":"过去完成进行时 had been + -ing。✓ had been searching the sea for weeks. ✗ searched / search / to search:had been 后接 -ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"\"The ship ___ have been an old liner.\"(对过去的推测\"一定曾是\")","options":["need","would","must","can"],"answer_index":2,"stem_cn":"那船一定曾是一艘旧客轮。","explanation_cn":"对过去的推测“一定曾是”用 must have been。✓ The ship must have been an old liner. ✗ can / need / would:推测过去用 must have been。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"\"piece together\" 的意思是:","options":["藏起来","拼凑、还原(信息)","卖个好价","撕成碎片"],"answer_index":1,"explanation_cn":"piece together = 把零散线索拼凑、还原。✓ piece together all the information 把所有线索拼凑起来。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"\"come to light\" 的意思是:","options":["打开电灯","天亮了","(真相)显露出来","变轻"],"answer_index":2,"explanation_cn":"come to light = (真相、信息)显露出来。✓ information that had come to light 浮现出来的线索。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"Why was the captain told to give up the search?","options":["He had already found the gold","A storm was coming","The crew were tired","The salvage operation had been a complete failure so far"],"answer_index":3,"passage":"The salvage operation had been a complete failure. The small ship Elkor, which had been searching the Barents Sea for weeks, was on its way home. A radio message from the mainland had been received by the ship''s captain instructing him to give up the search. The captain knew that another attempt would be made later, for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion. Despite the message, the captain of the Elkor decided to try once more. The sea bed was scoured with powerful nets, and there was tremendous excitement on board when a chest was raised from the bottom. Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong. What they had in fact found was a ship that had been sunk many years before. The chest contained the personal belongings of a sailor, Alan Fielding. There were books, clothing, and photographs, together with letters that the sailor had once received from his wife. The captain ordered his men to salvage as much as possible from the wreck. Nothing of great value was found, but the many items that were brought to the surface proved to be of great interest. From a heavy bronze bell that was raised, the captain realized that the ship must have been an old ocean liner. In another chest, which held the belongings of a ship''s officer, there was an unfinished letter that had been written decades earlier. The captain learned from the letter that the name of the lost ship was the Karen. The most valuable find of all was the ship''s logbook, parts of which it was still possible to read. From this the captain was able to piece together all the information that had come to light. The Karen had been sailing across the sea to deliver her cargo when she was caught in a violent storm and went down. This was later confirmed by a maritime historian after the Elkor had returned home. All the items that were found were sent to a maritime museum.","explanation_cn":"课文说 The salvage operation had been a complete failure——打捞一直毫无结果,所以让他放弃。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"How did the captain finally learn the lost ship''s story?","options":["By reading a newspaper","By piecing together clues from the ship''s logbook","By asking the sailors","By simply guessing"],"answer_index":1,"passage":"The salvage operation had been a complete failure. The small ship Elkor, which had been searching the Barents Sea for weeks, was on its way home. A radio message from the mainland had been received by the ship''s captain instructing him to give up the search. The captain knew that another attempt would be made later, for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion. Despite the message, the captain of the Elkor decided to try once more. The sea bed was scoured with powerful nets, and there was tremendous excitement on board when a chest was raised from the bottom. Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong. What they had in fact found was a ship that had been sunk many years before. The chest contained the personal belongings of a sailor, Alan Fielding. There were books, clothing, and photographs, together with letters that the sailor had once received from his wife. The captain ordered his men to salvage as much as possible from the wreck. Nothing of great value was found, but the many items that were brought to the surface proved to be of great interest. From a heavy bronze bell that was raised, the captain realized that the ship must have been an old ocean liner. In another chest, which held the belongings of a ship''s officer, there was an unfinished letter that had been written decades earlier. The captain learned from the letter that the name of the lost ship was the Karen. The most valuable find of all was the ship''s logbook, parts of which it was still possible to read. From this the captain was able to piece together all the information that had come to light. The Karen had been sailing across the sea to deliver her cargo when she was caught in a violent storm and went down. This was later confirmed by a maritime historian after the Elkor had returned home. All the items that were found were sent to a maritime museum.","explanation_cn":"课文说 From this the captain was able to piece together all the information——船长靠航海日志把线索拼凑出真相。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"Whose belongings were in the first chest?","options":["No one''s","The captain of the Elkor","A sailor named Alan Fielding","A famous artist"],"answer_index":2,"audio":"The salvage operation had been a complete failure. The small ship Elkor, which had been searching the Barents Sea for weeks, was on its way home. A radio message from the mainland had been received by the ship''s captain instructing him to give up the search. The captain knew that another attempt would be made later, for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion. Despite the message, the captain of the Elkor decided to try once more. The sea bed was scoured with powerful nets, and there was tremendous excitement on board when a chest was raised from the bottom. Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong. What they had in fact found was a ship that had been sunk many years before. The chest contained the personal belongings of a sailor, Alan Fielding. There were books, clothing, and photographs, together with letters that the sailor had once received from his wife. The captain ordered his men to salvage as much as possible from the wreck. Nothing of great value was found, but the many items that were brought to the surface proved to be of great interest. From a heavy bronze bell that was raised, the captain realized that the ship must have been an old ocean liner. In another chest, which held the belongings of a ship''s officer, there was an unfinished letter that had been written decades earlier. The captain learned from the letter that the name of the lost ship was the Karen. The most valuable find of all was the ship''s logbook, parts of which it was still possible to read. From this the captain was able to piece together all the information that had come to light. The Karen had been sailing across the sea to deliver her cargo when she was caught in a violent storm and went down. This was later confirmed by a maritime historian after the Elkor had returned home. All the items that were found were sent to a maritime museum.","explanation_cn":"课文说 The chest contained the personal belongings of a sailor, Alan Fielding——第一个箱子里是水手艾伦·菲尔丁的物品。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l32',10,NULL,'choice','{"stem":"Where were the found items finally sent?","options":["To a maritime museum","To the crew''s homes","Back into the sea","To a bank"],"answer_index":0,"audio":"The salvage operation had been a complete failure. The small ship Elkor, which had been searching the Barents Sea for weeks, was on its way home. A radio message from the mainland had been received by the ship''s captain instructing him to give up the search. The captain knew that another attempt would be made later, for the sunken ship he was trying to find had been carrying a precious cargo of gold bullion. Despite the message, the captain of the Elkor decided to try once more. The sea bed was scoured with powerful nets, and there was tremendous excitement on board when a chest was raised from the bottom. Though the crew were at first under the impression that the lost ship had been found, the contents of the chest proved them wrong. What they had in fact found was a ship that had been sunk many years before. The chest contained the personal belongings of a sailor, Alan Fielding. There were books, clothing, and photographs, together with letters that the sailor had once received from his wife. The captain ordered his men to salvage as much as possible from the wreck. Nothing of great value was found, but the many items that were brought to the surface proved to be of great interest. From a heavy bronze bell that was raised, the captain realized that the ship must have been an old ocean liner. In another chest, which held the belongings of a ship''s officer, there was an unfinished letter that had been written decades earlier. The captain learned from the letter that the name of the lost ship was the Karen. The most valuable find of all was the ship''s logbook, parts of which it was still possible to read. From this the captain was able to piece together all the information that had come to light. The Karen had been sailing across the sea to deliver her cargo when she was caught in a violent storm and went down. This was later confirmed by a maritime historian after the Elkor had returned home. All the items that were found were sent to a maritime museum.","explanation_cn":"课文说 All the items that were found were sent to a maritime museum——找到的物件都送进了海事博物馆。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l33',3,7,33,'A Day to Remember','难忘的一天','enough 的位置(well enough / enough time / hot enough to do)、现在分词表伴随(smashing / sending)、discover 与 invent 的区别、beside 与 besides 的区别、had to do(不得不·实际做了)与 should have done(本应做却没做)(原创承载 NCE3 L33 考点·轻净化+美式化:啤酒瓶→汽水瓶、去掉宝宝划伤细节;挡风玻璃 windshield、卡车 truck、初学司机 student driver、故事移到芝加哥郊区·连环倒霉喜剧内核原样保留)','我们都经历过诸事不顺的日子。一天也许开头还算顺利,可突然之间,一切好像都失了控。总是这样:一大堆事情偏偏挑在同一刻出岔子,仿佛一件不起眼的小事引发了一连串连锁反应。假设你正一边做饭,一边照看宝宝。这时电话响了——这成了一连串意外灾祸的序幕。你在讲电话,宝宝一把扯下桌布,打碎了你一半的好瓷器。你匆匆挂断电话,去收拾宝宝和碎瓷片。与此同时,饭菜煮糊了。仿佛这还不够让你崩溃,你丈夫回来了,还意外地带回三位客人来吃晚饭。事情也能大规模地出岔子,枫叶镇——芝加哥的一个郊区——最近就有不少人领教了这一点。一天傍晚的高峰时段,两辆车相撞,两位司机都吵了起来。紧跟在这两辆车后面的,恰好是一位初学开车的女司机。她一下子慌了神,把车停住了。这一停,让跟在她后面的司机猛踩刹车。那司机的妻子正坐在他旁边,手里捧着一个大蛋糕。她被向前一甩,蛋糕直接穿过挡风玻璃,落在了马路上。一个正驶近、与那辆车并排的卡车司机,看见一个蛋糕在空中飞,猛地停了车。卡车上装满了空汽水瓶,几百个瓶子从车尾滑落,滚到了马路上。这又引发了一场怒气冲冲的争吵。与此同时,后面的车堵成了一片。警察花了将近一个小时才让交通重新动起来。这期间,卡车司机不得不扫起几百个碎瓶子。这场混乱里只有两条流浪狗得了好处,它们贪婪地把剩下的蛋糕一扫而光。这真是倒霉透顶的一天!','{"q":"Listen and answer — What began the series of traffic accidents?","options":["A student driver panicked and stopped her car","A truck lost its brakes","A storm hit the road","A dog ran into the street"],"answer_index":0}'::jsonb,'{"title":"enough 的位置 / 现在分词表伴随 / discover vs invent / beside vs besides / had to vs should have","intro":"①enough 放在形容词/副词之后(good enough / well enough),但放在名词之前(enough time);“…到足以…”用 形容词 + enough + to do(hot enough to burn)。②现在分词表示同时发生的伴随动作:pulled the cloth off, smashing the dishes。③discover 是“发现(本已存在的)”,invent 是“发明(原来没有的)”。④beside 是“在…旁边”,besides 是“除…之外(还)”。⑤had to do=不得不(实际做了);should have done=本应做却没做。","table":{"headers":["用法","意思","例子"],"rows":[["adj/adv + enough / enough + 名词","足够…","begin well enough"],["现在分词表伴随","同时发生的动作","…off, smashing the dishes"],["discover / invent;beside / besides","发现/发明;旁边/除…之外","sitting beside him"],["had to do / should have done","不得不 / 本应却没","had to sweep up bottles"]]},"specialRules":[{"rule":"enough 修饰形容词/副词时放其后(warm enough),修饰名词时放其前(enough money);“形容词 + enough + to do”表示“…到足以…”。","mark":"enough 的位置"},{"rule":"beside=在…旁边(sit beside me);besides=除…之外还有(besides the cake, …)。一字之差意思不同。","mark":"beside ≠ besides"},{"rule":"美式:windshield(英式 windscreen)、truck(英式 lorry)、student driver(英式 learner driver)、soda(英式 fizzy drink)。本课已按美语写。","mark":"windshield / truck"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l33',1,NULL,'We have all experienced days when everything goes wrong. A day may begin well enough, but suddenly everything seems to get out of control. What invariably happens is that a great number of things choose to go wrong at precisely the same moment. It is as if a single unimportant event set up a chain of reactions.','我们都经历过诸事不顺的日子。一天也许开头还算顺利,可突然之间,一切好像都失了控。总是这样:一大堆事情偏偏挑在同一刻出岔子,仿佛一件不起眼的小事引发了一连串连锁反应。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l33',2,NULL,'Suppose that you are preparing a meal and keeping an eye on the baby at the same time. The telephone rings, and this marks the prelude to an unforeseen series of catastrophes. While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery. You hang up hurriedly and attend to the baby and the broken dishes.','假设你正一边做饭,一边照看宝宝。这时电话响了——这成了一连串意外灾祸的序幕。你在讲电话,宝宝一把扯下桌布,打碎了你一半的好瓷器。你匆匆挂断电话,去收拾宝宝和碎瓷片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l33',3,NULL,'Meanwhile, the meal gets burnt. As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner. Things can go wrong on a big scale, as a number of people recently discovered in Maplewood, a suburb of Chicago. During the rush hour one evening, two cars collided and both drivers began to argue.','与此同时,饭菜煮糊了。仿佛这还不够让你崩溃,你丈夫回来了,还意外地带回三位客人来吃晚饭。事情也能大规模地出岔子,枫叶镇——芝加哥的一个郊区——最近就有不少人领教了这一点。一天傍晚的高峰时段,两辆车相撞,两位司机都吵了起来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l33',4,NULL,'The woman immediately behind the two cars happened to be a student driver. She suddenly got into a panic and stopped her car. This made the driver following her brake hard. His wife was sitting beside him holding a large cake. As she was thrown forward, the cake went right through the windshield and landed on the road.','紧跟在这两辆车后面的,恰好是一位初学开车的女司机。她一下子慌了神,把车停住了。这一停,让跟在她后面的司机猛踩刹车。那司机的妻子正坐在他旁边,手里捧着一个大蛋糕。她被向前一甩,蛋糕直接穿过挡风玻璃,落在了马路上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l33',5,NULL,'Seeing a cake flying through the air, a truck driver who was drawing up alongside the car pulled up all of a sudden. The truck was loaded with empty soda bottles, and hundreds of them slid off onto the road. It took the police nearly an hour to get the traffic on the move again. In the meantime, the truck driver had to sweep up hundreds of broken bottles. Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake. It was just one of those days!','一个正驶近、与那辆车并排的卡车司机,看见一个蛋糕在空中飞,猛地停了车。卡车上装满了空汽水瓶,几百个瓶子从车尾滑落,滚到了马路上。警察花了将近一个小时才让交通重新动起来。这期间,卡车司机不得不扫起几百个碎瓶子。这场混乱里只有两条流浪狗得了好处,它们贪婪地把剩下的蛋糕一扫而光。这真是倒霉透顶的一天!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
