INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l33','get out of control','',NULL,'/ɡet aʊt əv kənˈtroʊl/','Suddenly everything got out of control.','突然之间一切都失控了。','The fire got out of control.','火势失去了控制。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l33','keep an eye on','',NULL,'/kiːp ən aɪ ɑːn/','She was keeping an eye on the baby.','她一直照看着宝宝。','Please keep an eye on my bags.','请帮我留意一下我的包。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l33','pile up','',NULL,'/paɪl ʌp/','The traffic piled up behind them.','车流在他们后面堵成一片。','Work piled up while I was away.','我不在时活儿越堆越多。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l33','all of a sudden','',NULL,'/ɔːl əv ə ˈsʌdən/','The truck stopped all of a sudden.','卡车猛地停了下来。','All of a sudden it started to rain.','突然下起雨来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp1','choice','{"stem":"\"A day may begin well ___.\"(表\"足够\",放在形容词/副词后面的那个词)","options":["enough","so","too","more"],"answer_index":0,"stem_cn":"一天可能开头还算顺利。","explanation_cn":"enough 修饰形容词/副词时放其后:well enough。✓ begin well enough. ✗ too / more / so:表“足够”放在 well 后面用 enough。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp1','choice','{"stem":"\"There wasn''t ___ time to cook the meal.\"(表\"足够的\",放在名词前面的那个词)","options":["quite","too","fairly","enough"],"answer_index":3,"stem_cn":"没有足够的时间做饭。","explanation_cn":"enough 修饰名词时放其前:enough time。✓ enough time to cook. ✗ too / fairly / quite:表“足够的”放在名词前用 enough。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp1','choice','{"stem":"\"The soup was ___ to burn my tongue.\"(\"热到足以烫舌\":形容词在前、表\"足够\"的词在后,再 + to do)","options":["so hot","enough hot","hot enough","too hot"],"answer_index":2,"stem_cn":"汤热得烫了我的舌头。","explanation_cn":"“…到足以…”用 形容词 + enough + to do。✓ hot enough to burn my tongue. ✗ enough hot(语序错)/ too hot(太热,不接 to 表结果)/ so hot:用 hot enough to do。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp2','choice','{"stem":"\"The baby pulled the cloth off, ___ half the dishes.\"(现在分词表同时发生\"打碎了…\")","options":["smash","smashing","to smash","smashed"],"answer_index":1,"stem_cn":"宝宝把桌布扯下,打碎了一半盘子。","explanation_cn":"现在分词表示同时发生的伴随动作。✓ pulled the cloth off, smashing the dishes. ✗ smashed / to smash / smash:伴随动作用 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp2','choice','{"stem":"\"She was thrown forward, ___ the cake through the window.\"(现在分词表伴随)","options":["to send","send","sending","sent"],"answer_index":2,"stem_cn":"她被向前甩去,把蛋糕从窗户甩了出去。","explanation_cn":"现在分词表伴随,“(结果)把蛋糕甩出去”。✓ thrown forward, sending the cake through the window. ✗ sent / to send / send:伴随用 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp2','choice','{"stem":"\"The bottles slid off the truck, ___ all over the road.\"(现在分词表伴随)","options":["rolled","roll","to roll","rolling"],"answer_index":3,"stem_cn":"瓶子从卡车上滑落,滚了一地。","explanation_cn":"现在分词表伴随,“(瓶子)滚了一地”。✓ slid off, rolling all over the road. ✗ rolled / to roll / roll:伴随用 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp3','choice','{"stem":"\"Columbus is said to have ___ America.\"(\"发现\"原本就存在的东西用哪个)","options":["created","built","discovered","invented"],"answer_index":2,"stem_cn":"据说哥伦布发现了美洲。","explanation_cn":"“发现(本已存在的东西)”用 discover。✓ discovered America. ✗ invented(发明)/ created / built:发现已存在的用 discover。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp3','choice','{"stem":"\"Edison ___ the light bulb.\"(\"发明\"原来没有的东西用哪个)","options":["found","met","discovered","invented"],"answer_index":3,"stem_cn":"爱迪生发明了电灯泡。","explanation_cn":"“发明(原来没有的东西)”用 invent。✓ invented the light bulb. ✗ discovered(发现)/ found / met:发明新东西用 invent。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp3','choice','{"stem":"\"A number of people recently ___ how badly a day can go.\"(\"发现、意识到(事实)\"用哪个)","options":["designed","produced","discovered","invented"],"answer_index":2,"stem_cn":"最近有些人发现,一天能糟到什么地步。","explanation_cn":"“发现、意识到(某个事实)”用 discover。✓ recently discovered how badly a day can go. ✗ invented / produced / designed:意识到事实用 discover。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp4','choice','{"stem":"\"His wife was sitting ___ him in the car.\"(\"在…旁边\"用哪个)","options":["besides","among","between","beside"],"answer_index":3,"stem_cn":"他妻子坐在他旁边。","explanation_cn":"“在…旁边”用 beside。✓ sitting beside him. ✗ besides(除…之外)/ between(两者之间)/ among(三者以上之中):在旁边用 beside。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp4','choice','{"stem":"\"___ the cake, there was nothing else to eat.\"(\"除…之外(还)\"用哪个)","options":["Besides","Behind","Beside","Between"],"answer_index":0,"stem_cn":"除了蛋糕,没别的可吃了。","explanation_cn":"“除…之外(还)”用 besides。✓ Besides the cake, there was nothing else. ✗ Beside(在旁边)/ Between / Behind:除…之外用 besides。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp4','choice','{"stem":"\"Come and sit ___ me.\"(\"坐在我身边\"用哪个)","options":["besides","beside","besides of","beside of"],"answer_index":1,"stem_cn":"过来坐在我旁边。","explanation_cn":"“坐在我身边”用 beside me。✓ sit beside me. ✗ besides(除…之外)/ beside of / besides of:在旁边用 beside。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp5','choice','{"stem":"\"The truck driver ___ sweep up hundreds of bottles.\"(\"不得不(实际做了)\"用 ___ do)","options":["should have","must to","had to","would have"],"answer_index":2,"stem_cn":"卡车司机不得不扫起几百个瓶子。","explanation_cn":"“不得不(而且实际做了)”用 had to + 动词原形。✓ had to sweep up bottles. ✗ should have(本应却没)/ would have / must to:实际做了的“不得不”用 had to。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp5','choice','{"stem":"\"You ___ told me earlier; now it''s too late.\"(\"本应做却没做\"的语气)","options":["should have","had to","would be","must have"],"answer_index":0,"stem_cn":"你本该早点告诉我,现在太晚了。","explanation_cn":"“本应做却没做”用 should have + 过去分词。✓ You should have told me earlier. ✗ had to(实际做了)/ must have(一定做了)/ would be:本应却没用 should have done。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp5','choice','{"stem":"\"Because the road was blocked, we ___ wait an hour.\"(\"不得不(结果做了)\"用 ___ wait)","options":["ought","should have","had to","might have"],"answer_index":2,"stem_cn":"因为路被堵,我们只好等了一小时。","explanation_cn":"“不得不(结果做了)”用 had to。✓ we had to wait an hour. ✗ should have(本应却没)/ might have / ought:实际做了用 had to。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp6','choice','{"stem":"\"A sudden terrible disaster is a ___.\"(\"大祸、灾难\"用哪个词)","options":["celebration","catastrophe","holiday","routine"],"answer_index":1,"stem_cn":"突如其来的大灾难。","explanation_cn":"突如其来的大灾难是 catastrophe。✓ a series of catastrophes. ✗ celebration 庆典;✗ holiday 假期;✗ routine 惯例——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp6','choice','{"stem":"\"When two cars crash into each other, they ___.\"(\"猛撞、相撞\"用哪个词)","options":["collide","wait","park","pass"],"answer_index":0,"stem_cn":"两车相撞。","explanation_cn":"两车猛地相撞是 collide。✓ two cars collided. ✗ park 停车;✗ wait 等待;✗ pass 经过——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',5,'am3_l33_gp6','choice','{"stem":"\"To eat something quickly and hungrily is to ___ it.\"(\"狼吞虎咽地吃\"用哪个词)","options":["waste","serve","devour","cook"],"answer_index":2,"stem_cn":"狼吞虎咽地吃掉。","explanation_cn":"狼吞虎咽地吃是 devour。✓ devoured what was left. ✗ cook 烹饪;✗ waste 浪费;✗ serve 端上——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"prelude 的意思是:","options":["间歇","序幕,前奏","结尾","高潮"],"answer_index":1,"explanation_cn":"prelude = 序幕、前奏。✓ the prelude to a series of catastrophes 一连串灾祸的序幕。\n顺带记:结尾 = ending;高潮 = climax;间歇 = interval."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"unforeseen 的意思是:","options":["常见的","计划好的","意料之外的","无聊的"],"answer_index":2,"explanation_cn":"unforeseen = 意料之外的。✓ an unforeseen series 意料之外的一连串事。\n顺带记:计划好的 = planned;常见的 = common;无聊的 = boring."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"suburb 的意思是:","options":["郊区","市中心","农场","港口"],"answer_index":0,"explanation_cn":"suburb = 郊区。✓ a suburb of Chicago 芝加哥的一个郊区。\n顺带记:市中心 = downtown;农场 = farm;港口 = harbor."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"panic 的意思是:","options":["耐心","平静","惊慌,恐慌","勇气"],"answer_index":2,"explanation_cn":"panic = 惊慌、恐慌。✓ got into a panic 慌了神。\n顺带记:平静 = calm;勇气 = courage;耐心 = patience."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"stray 的意思是:","options":["迷失的,离群的","凶猛的","温顺的","纯种的"],"answer_index":0,"explanation_cn":"stray = 迷失的、离群的。✓ two stray dogs 两条流浪狗。\n顺带记:温顺的 = tame;凶猛的 = fierce;纯种的 = purebred."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',6,NULL,'choice','{"stem":"greedily 的意思是:","options":["礼貌地","贪婪地","安静地","缓慢地"],"answer_index":1,"explanation_cn":"greedily = 贪婪地。✓ greedily devoured the cake 贪婪地把蛋糕吃光。\n顺带记:礼貌地 = politely;缓慢地 = slowly;安静地 = quietly."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',7,NULL,'cloze','{"stem":"第 1 空","context":"We have all experienced days when everything goes wrong. A day may begin well ___1___, but then a chain of unforeseen events follows. In one suburb, two cars ___2___ during rush hour. A cake flew through a windshield, and a truck driver ___3___ alongside stopped suddenly. In the end he ___4___ to sweep up hundreds of bottles.","blank_no":1,"options":["enough","too","very","so"],"answer_index":0,"explanation_cn":"enough 放在形容词/副词后面:well enough。✓ A day may begin well enough."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',7,NULL,'cloze','{"stem":"第 2 空","context":"We have all experienced days when everything goes wrong. A day may begin well ___1___, but then a chain of unforeseen events follows. In one suburb, two cars ___2___ during rush hour. A cake flew through a windshield, and a truck driver ___3___ alongside stopped suddenly. In the end he ___4___ to sweep up hundreds of bottles.","blank_no":2,"options":["collided","invented","devoured","panicked"],"answer_index":0,"explanation_cn":"“(两车)相撞”用 collide,过去式 collided。✓ two cars collided during rush hour."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',7,NULL,'cloze','{"stem":"第 3 空","context":"We have all experienced days when everything goes wrong. A day may begin well ___1___, but then a chain of unforeseen events follows. In one suburb, two cars ___2___ during rush hour. A cake flew through a windshield, and a truck driver ___3___ alongside stopped suddenly. In the end he ___4___ to sweep up hundreds of bottles.","blank_no":3,"options":["drawing up","drawn up","draws up","draw up"],"answer_index":0,"explanation_cn":"“(车辆)驶近、靠上来”用现在分词 drawing up 作定语。✓ a truck driver drawing up alongside the car."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',7,NULL,'cloze','{"stem":"第 4 空","context":"We have all experienced days when everything goes wrong. A day may begin well ___1___, but then a chain of unforeseen events follows. In one suburb, two cars ___2___ during rush hour. A cake flew through a windshield, and a truck driver ___3___ alongside stopped suddenly. In the end he ___4___ to sweep up hundreds of bottles.","blank_no":4,"options":["had","should","would","ought"],"answer_index":0,"explanation_cn":"“不得不(实际做了)”用 had to。✓ In the end he had to sweep up hundreds of bottles."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',8,NULL,'choice','{"stem":"What started the whole chain of accidents on the road?","options":["A student driver panicked and stopped her car","A dog ran across the road","The police arrived","A truck broke down"],"answer_index":0,"explanation_cn":"课文说 The woman…happened to be a student driver. She suddenly got into a panic and stopped her car——初学司机一慌把车停住,由此引发连环事故。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',8,NULL,'choice','{"stem":"What happened to the cake?","options":["It was eaten at dinner","It fell on the kitchen floor","It was sold at a store","It flew through the windshield onto the road"],"answer_index":3,"explanation_cn":"课文说 the cake went right through the windshield and landed on the road——蛋糕穿过挡风玻璃落到马路上。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',8,NULL,'choice','{"stem":"Who benefited from all the confusion?","options":["The truck driver","Two stray dogs that devoured the cake","The police officers","The student driver"],"answer_index":1,"explanation_cn":"课文说 Only two stray dogs benefited…they greedily devoured what was left of the cake——只有两条流浪狗把蛋糕吃了,占了便宜。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',9,NULL,'choice','{"stem":"你想说\"宝宝扯下桌布,打碎了一半盘子\"(现在分词表伴随):","options":["The baby pulled the cloth off, smashed half the dishes.","The baby pulled the cloth off, to smash half the dishes.","The baby pulled the cloth off, smash half the dishes.","The baby pulled the cloth off, smashing half the dishes."],"answer_index":3,"explanation_cn":"现在分词表示同时发生的伴随动作,用 smashing(不是 smashed / to smash)。✓ The baby pulled the cloth off, smashing half the dishes. 场合:一个动作紧跟着带来的结果。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',9,NULL,'choice','{"stem":"你想说\"他妻子坐在他旁边\"(beside):","options":["His wife was sitting beside him.","His wife was sitting beside of him.","His wife was sitting beside to him.","His wife was sitting besides him."],"answer_index":0,"explanation_cn":"“在…旁边”用 beside(不是 besides)。✓ His wife was sitting beside him. 场合:说某人在另一人身旁。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',9,NULL,'choice','{"stem":"你想说\"卡车司机不得不扫起几百个瓶子\"(had to do):","options":["The truck driver should have swept up hundreds of bottles.","The truck driver had to sweep up hundreds of bottles.","The truck driver had to swept up hundreds of bottles.","The truck driver must to sweep up hundreds of bottles."],"answer_index":1,"explanation_cn":"“不得不(而且实际做了)”用 had to;should have swept 意思是“本应扫却没扫”,与事实不符。✓ The truck driver had to sweep up hundreds of bottles. 场合:被迫做并且真的做了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"catastrophe 的意思是:","options":["惯例","庆典","假期","大祸,灾难"],"answer_index":3,"explanation_cn":"catastrophe = 大祸、灾难。✓ a series of catastrophes."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"devour 的意思是:","options":["狼吞虎咽地吃","端上","浪费","烹饪"],"answer_index":0,"explanation_cn":"devour = 狼吞虎咽地吃。✓ greedily devoured the cake 把蛋糕一扫而光。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"\"A day may begin well ___.\"(表\"足够\",放在形容词/副词后面)","options":["too","more","so","enough"],"answer_index":3,"stem_cn":"一天可能开头还算顺利。","explanation_cn":"enough 放在形容词/副词后面:well enough。✓ A day may begin well enough. ✗ too / more / so:表“足够”放在 well 后面用 enough。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"\"His wife was sitting ___ him.\"(\"在…旁边\"用哪个)","options":["among","besides","beside","between"],"answer_index":2,"stem_cn":"他妻子坐在他旁边。","explanation_cn":"“在…旁边”用 beside。✓ His wife was sitting beside him. ✗ besides(除…之外)/ between / among:在旁边用 beside。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"\"keep an eye on\" 的意思是:","options":["视而不见","照看,留意","眨眼","闭上眼睛"],"answer_index":1,"explanation_cn":"keep an eye on = 照看、留意。✓ keeping an eye on the baby 照看着宝宝。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"\"all of a sudden\" 的意思是:","options":["慢慢地","永远地","一如往常","突然地"],"answer_index":3,"explanation_cn":"all of a sudden = 突然地。✓ pulled up all of a sudden 猛地停下。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"According to the passage, what usually happens on a ''bad day''?","options":["Everything is fixed quickly","Nothing important happens","Many things go wrong at exactly the same time","Only one small thing goes wrong"],"answer_index":2,"passage":"We have all experienced days when everything goes wrong. A day may begin well enough, but suddenly everything seems to get out of control. What invariably happens is that a great number of things choose to go wrong at precisely the same moment. It is as if a single unimportant event set up a chain of reactions. Suppose that you are preparing a meal and keeping an eye on the baby at the same time. The telephone rings, and this marks the prelude to an unforeseen series of catastrophes. While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery. You hang up hurriedly and attend to the baby and the broken dishes. Meanwhile, the meal gets burnt. As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner. Things can go wrong on a big scale, as a number of people recently discovered in Maplewood, a suburb of Chicago. During the rush hour one evening, two cars collided and both drivers began to argue. The woman immediately behind the two cars happened to be a student driver. She suddenly got into a panic and stopped her car. This made the driver following her brake hard. His wife was sitting beside him holding a large cake. As she was thrown forward, the cake went right through the windshield and landed on the road. Seeing a cake flying through the air, a truck driver who was drawing up alongside the car pulled up all of a sudden. The truck was loaded with empty soda bottles, and hundreds of them slid off the back of the vehicle and onto the road. This led to yet another angry argument. Meanwhile, the traffic piled up behind. It took the police nearly an hour to get the traffic on the move again. In the meantime, the truck driver had to sweep up hundreds of broken bottles. Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake. It was just one of those days!","explanation_cn":"课文说 a great number of things choose to go wrong at precisely the same moment——糟糕的一天,一堆事偏偏同时出岔子。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"Why did the truck driver stop so suddenly?","options":["The police stopped him","He saw a cake flying through the air","His engine failed","A dog blocked the road"],"answer_index":1,"passage":"We have all experienced days when everything goes wrong. A day may begin well enough, but suddenly everything seems to get out of control. What invariably happens is that a great number of things choose to go wrong at precisely the same moment. It is as if a single unimportant event set up a chain of reactions. Suppose that you are preparing a meal and keeping an eye on the baby at the same time. The telephone rings, and this marks the prelude to an unforeseen series of catastrophes. While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery. You hang up hurriedly and attend to the baby and the broken dishes. Meanwhile, the meal gets burnt. As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner. Things can go wrong on a big scale, as a number of people recently discovered in Maplewood, a suburb of Chicago. During the rush hour one evening, two cars collided and both drivers began to argue. The woman immediately behind the two cars happened to be a student driver. She suddenly got into a panic and stopped her car. This made the driver following her brake hard. His wife was sitting beside him holding a large cake. As she was thrown forward, the cake went right through the windshield and landed on the road. Seeing a cake flying through the air, a truck driver who was drawing up alongside the car pulled up all of a sudden. The truck was loaded with empty soda bottles, and hundreds of them slid off the back of the vehicle and onto the road. This led to yet another angry argument. Meanwhile, the traffic piled up behind. It took the police nearly an hour to get the traffic on the move again. In the meantime, the truck driver had to sweep up hundreds of broken bottles. Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake. It was just one of those days!","explanation_cn":"课文说 Seeing a cake flying through the air, a truck driver…pulled up all of a sudden——卡车司机看见蛋糕飞过才急停。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"Where did the chain of traffic accidents happen?","options":["On a highway at dawn","On a quiet country road","In the city center at night","In a suburb during rush hour"],"answer_index":3,"audio":"We have all experienced days when everything goes wrong. A day may begin well enough, but suddenly everything seems to get out of control. What invariably happens is that a great number of things choose to go wrong at precisely the same moment. It is as if a single unimportant event set up a chain of reactions. Suppose that you are preparing a meal and keeping an eye on the baby at the same time. The telephone rings, and this marks the prelude to an unforeseen series of catastrophes. While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery. You hang up hurriedly and attend to the baby and the broken dishes. Meanwhile, the meal gets burnt. As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner. Things can go wrong on a big scale, as a number of people recently discovered in Maplewood, a suburb of Chicago. During the rush hour one evening, two cars collided and both drivers began to argue. The woman immediately behind the two cars happened to be a student driver. She suddenly got into a panic and stopped her car. This made the driver following her brake hard. His wife was sitting beside him holding a large cake. As she was thrown forward, the cake went right through the windshield and landed on the road. Seeing a cake flying through the air, a truck driver who was drawing up alongside the car pulled up all of a sudden. The truck was loaded with empty soda bottles, and hundreds of them slid off the back of the vehicle and onto the road. This led to yet another angry argument. Meanwhile, the traffic piled up behind. It took the police nearly an hour to get the traffic on the move again. In the meantime, the truck driver had to sweep up hundreds of broken bottles. Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake. It was just one of those days!","explanation_cn":"课文说 in Maplewood, a suburb of Chicago…During the rush hour——事故发生在郊区的高峰时段。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l33',10,NULL,'choice','{"stem":"How long did it take the police to get traffic moving again?","options":["Nearly an hour","Half a day","All night","A few minutes"],"answer_index":0,"audio":"We have all experienced days when everything goes wrong. A day may begin well enough, but suddenly everything seems to get out of control. What invariably happens is that a great number of things choose to go wrong at precisely the same moment. It is as if a single unimportant event set up a chain of reactions. Suppose that you are preparing a meal and keeping an eye on the baby at the same time. The telephone rings, and this marks the prelude to an unforeseen series of catastrophes. While you are on the phone, the baby pulls the tablecloth off the table, smashing half your best crockery. You hang up hurriedly and attend to the baby and the broken dishes. Meanwhile, the meal gets burnt. As if this were not enough to reduce you to tears, your husband arrives, unexpectedly bringing three guests to dinner. Things can go wrong on a big scale, as a number of people recently discovered in Maplewood, a suburb of Chicago. During the rush hour one evening, two cars collided and both drivers began to argue. The woman immediately behind the two cars happened to be a student driver. She suddenly got into a panic and stopped her car. This made the driver following her brake hard. His wife was sitting beside him holding a large cake. As she was thrown forward, the cake went right through the windshield and landed on the road. Seeing a cake flying through the air, a truck driver who was drawing up alongside the car pulled up all of a sudden. The truck was loaded with empty soda bottles, and hundreds of them slid off the back of the vehicle and onto the road. This led to yet another angry argument. Meanwhile, the traffic piled up behind. It took the police nearly an hour to get the traffic on the move again. In the meantime, the truck driver had to sweep up hundreds of broken bottles. Only two stray dogs benefited from all this confusion, for they greedily devoured what was left of the cake. It was just one of those days!","explanation_cn":"课文说 It took the police nearly an hour to get the traffic on the move again——警察花了近一小时才疏通交通。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
